    "d": 2,
    "en": "Read the following extract and answer the questions that follow : 4 LinguisticdiversityofIndia How many languages do we have in India ? The answer depends on how one counts it. The latest information that we have is from the Census of India held in 2011. This census recorded more than 1300 distinct languages which people mentioned as their mother tongues. These languages were grouped together under some major languages. For",
