    "en": "Read the case given below carefully and answer the questions that follow : 4 The Sense of Collective Belonging This sense of collective belonging came partly through the experience of united struggles. But there were also a variety of cultural processes nd fiction, folklore and songs, popular prints and symbols, all played a part in the making of nationalism. The identity of the nation, as you know, is most often symbolised in a figure or image. This helps create an image with which people can identify the nation. It was in the twentieth century, with the growth of nationalism, that the identity of India came to be visually associated with the image of Bharat Mata. The image was first created by Bankim Page 9 hymn to the motherland. Later it was included in his novel Anandamath",
