    "en": "Read the given source and answer the questions that follow : (3×4=12) WHY NEWSPAPERS ? ‘Krishnaji Trimbuck Ranade inhabitant of Poona intends to publish a Newspaper in the Marathi Language with a view of affording useful information on every topic of local interest. It will be open for free",
