        "en": "hhattisgarhi, Rajasthani and many others were grouped together under ‘Hindi’. Even after this grouping, the Census found 121 major languages. Of these 22 languages are now included in the Eighth Schedule of the Indian Constitution and are therefore called ‘Scheduled Languages’. Others",
