        "en": "uring the First World War, under the Defence of India Rules, 22 newspapers had to furnish securities. Of these, 18 shut down rather than comply with government orders. The Sedition Committee Report under Rowlatt in 1919 further strengthened controls that led to imposition of penalties on various newspapers. At the outbreak of the Second World War, the ‘Defence of India Act’ was passed, allowing censoring of reports of war-related topics. All reports about the Quit India Movement came under its purview. In August 1942, about 90 newspapers were suppressed. # 32/S/2 (35.1) Why were newspapers suppressed in 1942? 1 (35.2) How did the colonial government’s policies affect nationalism? 1 (35.3) Examine the role of the press in colonial India. 2",
