    "en": "Read the given source and answer the questions that follow : Sardar Sarovar Sardar Sarovar Dam has been built over the Narmada River in Gujarat. This is one of the largest water resource projects of India covering four states — Maharashtra, Madhya Pradesh, Gujarat and Rajasthan. The Sardar Sarovar project would meet the requirement of water in drought- prone and desert areas. Sardar Sarovar Project will provide irrigation facilities to 18.45 lakh hectare of land, covering 3112 villages in 15 districts of Gujarat. It will also irrigate 2,46,000 hectare of land in the strategic desert districts of Barmer and Jalore in Rajasthan and 37,500 hectare land in the tribal hilly tract of Maharashtra through lift.",
